// ── fetch handler ─────────────────────────────────────────────────────────────

async function handleFetch(request, env) {
  const RESEND_KEY = env.RESEND_KEY;
  if (request.method === "OPTIONS") {
    return new Response(null, { headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
    }});
  }

  if (request.method === "GET") {
    const u = new URL(request.url);
    if (u.searchParams.has("debug")) {
      const bq = await apiGet({ action: "bouquet" });
      const ri = await apiGet({ action: "reseller_info" });
      // Zero list ops: read __keys__ index instead of kv.list()
      const _kr = await env.TRIALS.get('__keys__') || '[]';
      const _ke = JSON.parse(_kr);
      const trials = { keys: _ke.map(e => ({ name: 'trial:' + e })) };
      return jsonRes({ bouquet: bq.text.slice(0,400), reseller: ri.text.slice(0,200), kv_keys: trials.keys.length });
    }
    return new Response("Mojo 4K Trial Worker — OK", { status: 200 });
  }

  if (request.method !== "POST") return jsonRes({ success: false, error: "POST only" }, 405);

  let body;
  try { body = await request.json(); }
  catch { return jsonRes({ success: false, error: "Ungültiges JSON" }, 400); }

  const name     = String(body.name || "").trim().slice(0, 100);
  const email    = String(body.email || "").trim().toLowerCase().slice(0, 200);
  const country  = String(body.country || "").trim().slice(0, 100);
  const device   = String(body.device || "").trim().slice(0, 100);
  const whatsapp = String(body.whatsapp || "").trim().slice(0, 50);
  const notes    = String(body.notes || "").trim().slice(0, 1000);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return jsonRes({ success: false, error: "Bitte geben Sie eine gültige E-Mail-Adresse ein." }, 400);
  }

  let step = "bouquet";
  try {
    // 1. Paket-ID ermitteln
    const bqRes = await apiGet({ action: "bouquet" });
    let packId = "all";
    if (bqRes.text.trim().startsWith("[") || bqRes.text.trim().startsWith("{")) {
      const arr = JSON.parse(bqRes.text);
      const list = Array.isArray(arr) ? arr : Object.values(arr);
      const pkg = list.find(b => (b.name || "").trim().toLowerCase() === PACK_NAME.toLowerCase());
      if (pkg) packId = pkg.id;
    }

    // 2. Demo-Linie erstellen
    step = "create_demo";
    let username = "", password = "";

    try {
      step = "create_demo";
      const crRes = await apiGet({
        action: "new", type: "m3u", sub: "99", pack: packId,
        notes: `Trial / mojo4k.de / ${email} | ${whatsapp || ""}`,
      });
      if (!crRes.text.trim().startsWith("[") && !crRes.text.trim().startsWith("{")) {
        throw new Error(`Panel kein JSON: ${crRes.text.slice(0, 200)}`);
      }
      const crData = JSON.parse(crRes.text);
      const item = Array.isArray(crData) ? crData[0] : crData;
      if (!item || String(item.status) !== "true") {
        throw new Error(`Panel: ${item?.message || JSON.stringify(item)}`);
      }

      // 3. Zugangsdaten extrahieren
      step = "extract";
      const rawUrl = item.url || "";
      try { const u = new URL(rawUrl); username = u.searchParams.get("username") || ""; password = u.searchParams.get("password") || ""; } catch {}

    } catch (panelErr) {
      const _dU = env.DEMO_USERNAME;
      const _dP = env.DEMO_PASSWORD;
      if (_dU && _dP) {
        username = _dU;
        password = _dP;
        console.log(`[fallback] Panel failed (${panelErr.message}) — using shared demo credentials`);
      } else {
        // Kein automatischer Zugang möglich: Lead nicht verlieren, Admin zum manuellen Senden benachrichtigen
        console.error(`[step=${step}] ${panelErr.message} — admin notified for manual trial`);
        step = "email_admin_manual";
        await sendEmail(ADMIN_EMAIL, `MANUELL / mojo4k.de / trial / ${name || "—"} / ${email}`, adminEmail(name, email, country, device, whatsapp, notes, "", "", "", panelErr.message), RESEND_KEY);
        return jsonRes({ success: true, pending: true });
      }
    }

    const m3uUrl = `${HOST}/get.php?username=${encodeURIComponent(username)}&password=${encodeURIComponent(password)}&type=m3u_plus&output=ts`;

    // 4. In KV speichern ZUERST (damit Trial immer gespeichert wird, auch wenn E-Mail fehlschlägt)
    step = "kv_store";
    let welcomeEmailId = null;
    const expiry = Date.now() + 24 * 60 * 60 * 1000;
    await env.TRIALS.put(
      `trial:${email}`,
      JSON.stringify({ name, email, whatsapp, site: 'mojo4k.de', username, password, m3uUrl, expiry, reminder_sent: false, followup_sent: false, welcome_email_id: null, created_at: Date.now() }),
      { expirationTtl: 30 * 24 * 60 * 60 }
    );
    // Update __keys__ index (read op, not list op — keeps KV list quota safe)
    try {
      const _existingKeys = JSON.parse(await env.TRIALS.get('__keys__') || '[]');
      if (!_existingKeys.includes(email)) {
        _existingKeys.push(email);
        await env.TRIALS.put('__keys__', JSON.stringify(_existingKeys), { expirationTtl: 90 * 24 * 60 * 60 });
      }
    } catch(_) {}
    // Zentralen KV-Reader benachrichtigen
    const _kvBody = JSON.stringify({ name, email, whatsapp, site: 'mojo4k.de', phone: whatsapp, created_at: Date.now() });
    const _kvPost = () => fetch('https://iptv-kv-reader.medmaar.workers.dev/add',
      { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: _kvBody });
    try { await _kvPost(); }
    catch(_) { try { await new Promise(r => setTimeout(r, 1500)); await _kvPost(); } catch(__) {} }

    // 5. Willkommens-E-Mail
    step = "email_client";
    welcomeEmailId = await sendEmail(email, "Ihr Mojo 4K Testzugang ist bereit – 24h Gratis aktiviert ✓", welcomeEmail(name, username, password, m3uUrl), RESEND_KEY);
    // Update KV with welcome_email_id for threading
    if (welcomeEmailId) {
      try {
        const _t = JSON.parse(await env.TRIALS.get(`trial:${email}`) || '{}');
        _t.welcome_email_id = welcomeEmailId;
        await env.TRIALS.put(`trial:${email}`, JSON.stringify(_t), { expirationTtl: 30 * 24 * 60 * 60 });
      } catch(_) {}
    }

    // 6. Admin-Benachrichtigung
    step = "email_admin";
    await sendEmail(ADMIN_EMAIL, `Automation / mojo4k.de / trial / ${name || "—"} / ${email}`, adminEmail(name, email, country, device, whatsapp, notes, username, password, m3uUrl), RESEND_KEY);

    return jsonRes({ success: true });

  } catch (err) {
    console.error(`[step=${step}]`, err.message);
    return jsonRes({ success: false, error: `[${step}] ${err.message}` }, 500);
  }
}

// ── cron handler ──────────────────────────────────────────────────────────────

async function handleScheduled(env) {
  const RESEND_KEY = env.RESEND_KEY;
  const now = Date.now();
  const FOUR_HOURS = 4 * 60 * 60 * 1000;
  const _keysRaw = await env.TRIALS.get('__keys__') || '[]';
  const _keyEmails = JSON.parse(_keysRaw);
  const keys = _keyEmails.map(e => ({ name: `trial:${e}` }));
  console.log(`[cron] ${keys.length} Tests geprüft`);

  for (const { name: key } of keys) {
    let trial;
    try { const raw = await env.TRIALS.get(key); if (!raw) continue; trial = JSON.parse(raw); } catch { continue; }
    const { name, email, username, password, m3uUrl, expiry, reminder_sent, followup_sent, welcome_email_id } = trial;

    if (!reminder_sent && now >= expiry - FOUR_HOURS && now < expiry) {
      try {
        await sendEmail(email, "Ihr Mojo 4K Testzugang ist bereit – 24h Gratis aktiviert ✓", reminderEmail(name, username, password, m3uUrl), RESEND_KEY, welcome_email_id);
        trial.reminder_sent = true;
        await env.TRIALS.put(key, JSON.stringify(trial), { expirationTtl: 30 * 24 * 60 * 60 });
        console.log(`[cron] Erinnerung → ${email}`);
      } catch (e) { console.error(`[cron] Fehler Erinnerung ${email}:`, e.message); }
    }

    if (!followup_sent && now >= expiry) {
      try {
        await sendEmail(email, "Ihr Mojo 4K Testzugang ist bereit – 24h Gratis aktiviert ✓", followupEmail(name), RESEND_KEY, welcome_email_id);
        trial.followup_sent = true;
        await env.TRIALS.put(key, JSON.stringify(trial), { expirationTtl: 30 * 24 * 60 * 60 });
        console.log(`[cron] Nachfass → ${email}`);
      } catch (e) { console.error(`[cron] Fehler Nachfass ${email}:`, e.message); }
    }
  }
}

